#!/usr/bin/env python3
"""Create the self-contained responsive Liga Portugal Betclic 2026/27 dashboard."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parent; S=ROOT/'source_snapshots'
fixtures=json.loads((S/'official_matches_compact.json').read_text())
standings=json.loads((S/'official_standings_compact.json').read_text())
rounds=json.loads((S/'official_rounds.json').read_text())
log=json.loads((S/'source_log.json').read_text())
clubs=sorted({m['home'] for m in fixtures}|{m['away'] for m in fixtures})
# Sanitization invariant: only official FT state 5 has goals; undefined kickoffs stay unconfirmed.
for m in fixtures:
    final=m.get('state_id')==5 and m.get('home_goals') is not None and m.get('away_goals') is not None
    if not final: m['home_goals']=m['away_goals']=None
payload={'fixtures':fixtures,'standings':standings,'rounds':rounds,'teams':clubs,'source':log}
data=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
cutoff=log['cutoff_local'].replace('T',' ').replace('-03:00',' BRT')[:19]
page=r'''<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#081c31"><title>Liga Portugal Betclic 2026/27 — Painel</title>
<style>
:root{--navy:#081c31;--navy2:#102b48;--red:#e10014;--gold:#f5c451;--bg:#f3f6fa;--card:#fff;--ink:#172433;--muted:#627386;--line:#e4eaf0;--green:#16865d}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,Arial;color:var(--ink)}header{background:linear-gradient(125deg,var(--navy),#19476a);color:#fff;padding:28px max(18px,calc((100vw - 1180px)/2));border-bottom:5px solid var(--red)}header .eyebrow{letter-spacing:.12em;text-transform:uppercase;color:#c5d8ea;font-size:.76rem;font-weight:700}h1{margin:.35rem 0;font-size:clamp(1.55rem,4vw,2.7rem);line-height:1.12}header p{margin:.45rem 0;color:#dbe6ef}.wrap{max-width:1180px;margin:auto;padding:18px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 16px}.card,.section{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:0 4px 18px #102b4810}.card{padding:15px}.card b{display:block;font-size:1.55rem;color:var(--navy)}.card span{font-size:.84rem;color:var(--muted)}.section{padding:18px;margin-bottom:15px}.section h2{margin:0 0 12px;font-size:1.22rem;color:var(--navy)}.section h3{margin:14px 0 8px;color:var(--navy);font-size:1rem}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.field{display:flex;flex-direction:column;gap:4px;min-width:180px;flex:1}.field label{font-size:.78rem;color:var(--muted);font-weight:700}select,button{font:inherit;border:1px solid #cbd5df;border-radius:9px;background:#fff;color:var(--ink);padding:9px 11px;min-height:42px}button{background:var(--navy);color:white;border-color:var(--navy);font-weight:700;cursor:pointer}button:hover{background:#17436b}a{color:#075b9a}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.86rem;min-width:720px}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.04em;background:#f8fafc;position:sticky;top:0}tbody tr:hover{background:#f5f9fc}.pos{font-weight:800;color:#657587;width:34px}.teamlink{border:0;padding:0;background:none;color:#075b9a;text-decoration:underline;cursor:pointer;min-height:auto;font-weight:700}.pill{display:inline-block;background:#edf3f8;border-radius:99px;padding:2px 8px;font-size:.78rem}.note{border-left:4px solid var(--gold);background:#fff8e5;border-radius:8px;padding:12px 14px;color:#564312;margin:10px 0}.muted{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.stat{background:#f5f8fb;border:1px solid var(--line);border-radius:10px;padding:10px}.stat b{display:block;font-size:1.1rem;color:var(--navy)}.stat span{font-size:.77rem;color:var(--muted)}.match{border-bottom:1px solid var(--line);padding:10px 2px;display:grid;grid-template-columns:68px minmax(100px,1fr) 65px minmax(100px,1fr) 130px;gap:8px;align-items:center}.match .score{text-align:center;font-weight:800}.match .date{font-size:.78rem;color:var(--muted)}.form{font-family:ui-monospace,monospace;letter-spacing:.08em}.green{color:var(--green)}footer{max-width:1180px;margin:0 auto 30px;padding:0 18px;color:var(--muted);font-size:.8rem}.small{font-size:.82rem}.empty{padding:14px;color:var(--muted);background:#f7f9fb;border-radius:9px}@media(max-width:760px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.wrap{padding:12px}.section{padding:14px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.match{grid-template-columns:55px minmax(90px,1fr) 50px minmax(90px,1fr);font-size:.85rem}.match .date:last-child{grid-column:2/-1}.field{min-width:145px}}@media(max-width:420px){.cards{gap:8px}.card{padding:11px}.card b{font-size:1.3rem}.match{grid-template-columns:45px 1fr 42px 1fr;gap:4px;font-size:.79rem}}
</style></head><body><header><div class="eyebrow">Painel independente · Época 2026/27</div><h1>Liga Portugal Betclic</h1><p>Classificação, calendário, forma, casa/fora e comparador de equipas</p><p id="cutoff" class="small"></p></header><main class="wrap"><div class="cards" id="summary"></div>
<section class="section"><h2>Classificação oficial</h2><div class="note"><b>Zonas oficiais — validação pendente:</b> os metadados de duas fichas oficiais da competição divergem nas posições de acesso às competições europeias. Para não atribuir vagas incorretas, o painel não colore nem rotula zonas europeias. A zona inferior também é exibida sem demarcações individuais até confirmação normativa independente. Classificação e estatísticas abaixo são reconciliadas com a tabela oficial.</div><div class="scroll"><table id="table"><thead><tr><th>#</th><th>Clube</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GM</th><th>GS</th><th>SG</th><th>Pts</th><th>Forma</th></tr></thead><tbody></tbody></table></div></section>
<section class="section"><h2>Perfil do clube</h2><div class="row"><div class="field"><label for="profileTeam">Selecione a equipe</label><select id="profileTeam"></select></div><div class="field"><label>Últimos cinco — jogos finalizados</label><div id="form" class="pill form">—</div></div></div><div id="profileStats" class="stats" style="margin-top:12px"></div><h3>Últimos cinco jogos</h3><div id="last5"></div></section>
<section class="section"><h2>Calendário e resultados</h2><div class="row"><div class="field"><label for="roundSelect">Jornada</label><select id="roundSelect"></select></div><div class="field"><label for="fixtureTeam">Filtrar por clube (opcional)</label><select id="fixtureTeam"></select></div></div><div id="fixtures" style="margin-top:10px"></div></section>
<section class="section"><h2>Top 5 — métricas</h2><div class="row"><div class="field"><label for="metricSelect">Métrica</label><select id="metricSelect"><option value="points">Pontos</option><option value="gf">Gols marcados</option><option value="ga">Menos gols sofridos</option><option value="wins">Vitórias</option><option value="draws">Empates</option><option value="loses">Derrotas</option><option value="btts">Ambas marcam</option><option value="over25">Mais de 2,5 gols</option><option value="clean">Jogos sem sofrer gol</option></select></div><div class="field"><label for="splitSelect">Recorte</label><select id="splitSelect"><option value="all">Geral</option><option value="home">Em casa</option><option value="away">Fora</option></select></div></div><div class="scroll" style="margin-top:10px"><table><thead><tr><th>#</th><th>Clube</th><th>Métrica</th><th>Jogos no recorte</th></tr></thead><tbody id="top5"></tbody></table></div></section>
<section class="section"><h2>Comparador de confronto</h2><p class="muted small">Estimativa descritiva a partir de gols observados por equipe no recorte casa/fora disponível; amostras ainda pequenas. Não é aconselhamento de apostas.</p><div class="row"><div class="field"><label for="homeTeam">Mandante</label><select id="homeTeam"></select></div><div class="field"><label for="awayTeam">Visitante</label><select id="awayTeam"></select></div></div><div id="estimate" style="margin-top:12px"></div><h3>Confrontos diretos registrados nesta época</h3><div id="h2h"></div></section>
<section class="section"><h2>Fontes, critérios e limites</h2><ul class="small"><li>Fonte primária: <a href="https://www.ligaportugal.pt/competition/911/liga-portugal-betclic/round/20262027" target="_blank" rel="noreferrer">Liga Portugal Betclic</a> e API oficial de calendário/tabela.</li><li>Verificação independente de resultados: <a href="https://site.api.espn.com/apis/site/v2/sports/soccer/por.1/scoreboard" target="_blank" rel="noreferrer">ESPN Soccer API</a>, por data UTC.</li><li>Resultados finais contam somente com estado oficial 5 e placar preenchido. O campo oficial hasOfficialResult é inconsistente e não é usado para classificar jogos.</li><li>Jogos sem hora confirmada não recebem horário inferido; placares provisórios de jogos não finalizados são ocultados.</li><li>Probabilidades 1-X-2 e estimativas de gols são Poisson simplificados e descritivos, com poucos jogos até agora; não representam modelo validado nem recomendação.</li><li>Última captura de dados: <b id="sourceCutoff"></b>. Uma atualização automática diária ainda depende de configuração e execução confirmada.</li></ul><p class="small">API: <a href="https://www.ligaportugal.pt/api/v1/competition/season/rounds?competition=ligaportugalbetclic&amp;season=20262027" target="_blank" rel="noreferrer">jornadas</a> · <a href="https://www.ligaportugal.pt/api/v2/competition/standings?competition=ligaportugalbetclic&amp;season=20262027" target="_blank" rel="noreferrer">classificação</a>.</p></section></main><footer>Dados consultados em {{CUTOFF}} (BRT). Uso informativo. A classificação oficial pode conter critérios regulamentares não reproduzidos por este painel.</footer>
<script id="data" type="application/json">{{DATA}}</script><script>
const D=JSON.parse(document.getElementById('data').textContent), F=D.fixtures, S=D.standings, T=D.teams, $=id=>document.getElementById(id), finals=F.filter(x=>x.state_id===5&&x.home_goals!==null&&x.away_goals!==null), rounds=[...new Set(F.map(x=>x.round))].sort((a,b)=>a-b);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('cutoff').textContent=`Corte dos dados: {{CUTOFF}} BRT · ${F.length} jogos previstos · ${finals.length} resultados confirmados`;$('sourceCutoff').textContent=`{{CUTOFF}} BRT`;
$('summary').innerHTML=[[T.length,'clubes'],[F.length,'jogos no calendário'],[finals.length,'resultados finais'],[F.length-finals.length,'por iniciar / sem final confirmado']].map(([n,l])=>`<div class="card"><b>${n}</b><span>${l}</span></div>`).join('');
const sort=S.slice().sort((a,b)=>a.position-b.position);$('table').querySelector('tbody').innerHTML=sort.map(r=>`<tr><td class="pos">${r.position}</td><td><button class="teamlink" data-team="${esc(r.team_name)}">${esc(r.team_name)}</button></td><td>${r.played}</td><td>${r.total_wins}</td><td>${r.total_draws}</td><td>${r.total_loses}</td><td>${r.total_goals_for}</td><td>${r.total_goals_against}</td><td>${r.totals_goals_difference>0?'+':''}${r.totals_goals_difference}</td><td><b>${r.points}</b></td><td class="form">${esc(r.form||'—')}</td></tr>`).join('');
function fill(sel,first='— selecione —'){ $(sel).innerHTML=`<option value="">${first}</option>`+T.map(t=>`<option>${esc(t)}</option>`).join('') }
['profileTeam','fixtureTeam','homeTeam','awayTeam'].forEach(x=>fill(x));rounds.forEach(r=>$('roundSelect').insertAdjacentHTML('beforeend',`<option value="${r}">Jornada ${r}</option>`));$('roundSelect').value=String(rounds.find(r=>F.some(x=>x.round===r&&x.state_id!==5))||1);
function teamMatches(team){return finals.filter(m=>m.home===team||m.away===team).sort((a,b)=>b.match_date_utc.localeCompare(a.match_date_utc))}
function stats(team,split='all'){let ms=finals.filter(m=>(m.home===team||m.away===team)&&(split==='all'||(split==='home'?m.home===team:m.away===team)));let w=0,d=0,l=0,gf=0,ga=0,btts=0,over=0,clean=0;for(const m of ms){let h=m.home===team,forg=h?m.home_goals:m.away_goals,ag=h?m.away_goals:m.home_goals;gf+=forg;ga+=ag;if(forg>ag)w++;else if(forg===ag)d++;else l++;if(m.home_goals>0&&m.away_goals>0)btts++;if(m.home_goals+m.away_goals>2.5)over++;if(ag===0)clean++}return {n:ms.length,w,d,l,loses:l,points:3*w+d,gf,ga,btts,over,clean}}
function showProfile(team){if(!team)return;let r=S.find(x=>x.team_name===team),s=stats(team), hs=stats(team,'home'),as=stats(team,'away'),ms=teamMatches(team).slice(0,5);$('profileStats').innerHTML=[[`${s.w}-${s.d}-${s.l}`,'V-E-D'],[`${s.gf}:${s.ga}`,'Gols feitos:sofridos'],[`${hs.n} jogos · ${hs.gf}:${hs.ga}`,'Casa'],[`${as.n} jogos · ${as.gf}:${as.ga}`,'Fora']].map(x=>`<div class="stat"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('');$('form').textContent=ms.length?ms.map(m=>{let gf=m.home===team?m.home_goals:m.away_goals,ga=m.home===team?m.away_goals:m.home_goals;return gf>ga?'V':gf===ga?'E':'D'}).join(' · '):'Sem resultados';$('last5').innerHTML=ms.length?ms.map(matchHtml).join(''):'<div class="empty">Ainda não há resultados finais.</div>'}
function timeLabel(m){if(!m.date_defined)return 'Horário a confirmar';const v=m.fixture_date_utc||m.match_date_utc;if(!v)return 'Data a confirmar';try{return new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Lisbon'}).format(new Date(v))+' (Lisboa)'}catch{return v}}
function matchHtml(m){let score=m.state_id===5&&m.home_goals!==null?`${m.home_goals}–${m.away_goals}`:'vs';return `<div class="match"><span class="pill">J${m.round}</span><span>${esc(m.home)}</span><span class="score">${score}</span><span>${esc(m.away)}</span><span class="date">${timeLabel(m)}</span></div>`}
function renderFixtures(){let rn=+$('roundSelect').value,team=$('fixtureTeam').value;let ms=F.filter(m=>m.round===rn&&(!team||m.home===team||m.away===team)).sort((a,b)=>String(a.fixture_date_utc||a.match_date_utc).localeCompare(String(b.fixture_date_utc||b.match_date_utc)));$('fixtures').innerHTML=ms.length?ms.map(matchHtml).join(''):'<div class="empty">Nenhum jogo para esse filtro.</div>'}
const metrics={points:['Pontos','points'],gf:['Gols marcados','gf'],ga:['Menos gols sofridos','ga'],wins:['Vitórias','w'],draws:['Empates','d'],loses:['Derrotas','l'],btts:['Ambas marcam','btts'],over25:['Mais de 2,5 gols','over'],clean:['Jogos sem sofrer gol','clean']};function renderTop(){let key=$('metricSelect').value,split=$('splitSelect').value,reverse=key==='ga'||key==='loses',arr=T.map(t=>({t,s:stats(t,split)})).sort((a,b)=>(reverse?a.s[key]-b.s[key]:b.s[key]-a.s[key])||a.t.localeCompare(b.t)).slice(0,5);$('top5').innerHTML=arr.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.t)}</td><td>${x.s[key]}${['btts','over25','clean'].includes(key)?` / ${x.s.n}`:''}</td><td>${x.s.n}</td></tr>`).join('')}
function pois(l,k){if(k<0)return 0;let p=Math.exp(-l),sum=p;for(let i=1;i<=k;i++){p*=l/i;sum+=p}return Math.max(0,Math.min(1,sum))}function prob(x){return Math.round(x*100)+'%'}function renderCompare(){let h=$('homeTeam').value,a=$('awayTeam').value;if(!h||!a||h===a){$('estimate').innerHTML='<div class="empty">Escolha duas equipes diferentes.</div>'; $('h2h').innerHTML='';return}let sh=stats(h,'home'),sa=stats(a,'away'),leagueHome=finals.reduce((x,m)=>x+m.home_goals,0)/Math.max(1,finals.length),leagueAway=finals.reduce((x,m)=>x+m.away_goals,0)/Math.max(1,finals.length),homeAvg=sh.n?sh.gf/sh.n:leagueHome,awayDef=sa.n?sa.ga/sa.n:leagueHome,awayAvg=sa.n?sa.gf/sa.n:leagueAway,homeDef=sh.n?sh.ga/sh.n:leagueAway;let lh=Math.max(.15,(homeAvg+awayDef)/2),la=Math.max(.15,(awayAvg+homeDef)/2);let pH=0,pD=0,pA=0;for(let i=0;i<9;i++)for(let j=0;j<9;j++){let q=pois(lh,i)-pois(lh,i-1),r=pois(la,j)-pois(la,j-1);if(i>j)pH+=q*r;else if(i===j)pD+=q*r;else pA+=q*r}let h2h=finals.filter(m=>(m.home===h&&m.away===a)||(m.home===a&&m.away===h));$('estimate').innerHTML=`<div class="stats"><div class="stat"><b>${prob(pH)}</b><span>Vitória ${esc(h)} (estimativa)</span></div><div class="stat"><b>${prob(pD)}</b><span>Empate (estimativa)</span></div><div class="stat"><b>${prob(pA)}</b><span>Vitória ${esc(a)} (estimativa)</span></div><div class="stat"><b>${lh.toFixed(2)} × ${la.toFixed(2)}</b><span>Gols esperados simplificados</span></div></div><p class="small muted">Base de gols casa ${sh.gf}/${sh.n||0} e gols sofridos fora ${sa.ga}/${sa.n||0}; amostra reduzida. Não é previsão validada.</p>`;$('h2h').innerHTML=h2h.length?h2h.sort((x,y)=>y.match_date_utc.localeCompare(x.match_date_utc)).map(matchHtml).join(''):'<div class="empty">Sem confronto direto finalizado nesta época.</div>'}
$('profileTeam').addEventListener('change',e=>showProfile(e.target.value));$('roundSelect').addEventListener('change',renderFixtures);$('fixtureTeam').addEventListener('change',renderFixtures);$('metricSelect').addEventListener('change',renderTop);$('splitSelect').addEventListener('change',renderTop);['homeTeam','awayTeam'].forEach(id=>$(id).addEventListener('change',renderCompare));$('table').addEventListener('click',e=>{let b=e.target.closest('[data-team]');if(b){$('profileTeam').value=b.dataset.team;showProfile(b.dataset.team)}});renderFixtures();renderTop();
</script></body></html>'''
page=page.replace('{{DATA}}',data).replace('{{CUTOFF}}',cutoff)
out=ROOT/'index.html';out.write_text(page,encoding='utf-8')
site=ROOT/'site';site.mkdir(exist_ok=True);(site/'index.html').write_text(page,encoding='utf-8');(site/'.nojekyll').write_text('')
print(f'Built {out} and {site}/index.html ({out.stat().st_size} bytes), {len(fixtures)} fixtures, {sum(m.get("state_id")==5 for m in fixtures)} finals, cutoff {cutoff} BRT')
